function defaultSettings(){return {
  unit:'cm', grid:true, snap:true, snapSize:10, wallSnap:true, objectSnap:true,
  labels:true, dimensions:true, clearances:true, zones:true, measurements:true,
  fixtures:true, furniture:true, haptics:true, reduceMotion:false, confirmDelete:true,
  performanceMode:'auto', theme:'pink', workspaceMode:'plan',
  autoFitOnOpen:true, showFitStatus:true, showIssueStatus:true, startupView:'rooms'
}}
function newLayout(name='Layout A', objects=[]){return {id:uid('layout'),name,objects,measurements:[],notes:[],createdAt:now(),updatedAt:now(),favorite:false}}
function defaultState(){return {
  version:3, settings:defaultSettings(), rooms:[], library:[], favoritePresetIds:[], recentPresetIds:[], roomTemplates:[],
  currentRoomId:null,currentLayoutId:null,selectedId:null,view:'rooms',zoom:1,
  history:[],future:[],measureDraft:null,activeTool:'select'
}}

let state = loadState();
