function exportModal(){modal('Export & share',`<div class="list"><button class="list-row" id="expPng"><span>🖼️ Export plan as PNG</span><span>›</span></button><button class="list-row" id="expProject"><span>📦 Export Dango room</span><span>JSON</span></button><button class="list-row" id="expFurniture"><span>🪑 Export object list</span><span>CSV</span></button><button class="list-row" id="expShopping"><span>🛒 Export shopping list</span><span>CSV</span></button><button class="list-row" id="expSummary"><span>📋 Copy room summary</span><span>›</span></button></div>`,m=>{$('#expPng',m).onclick=exportPNG;$('#expProject',m).onclick=exportProject;$('#expFurniture',m).onclick=exportFurnitureCSV;$('#expShopping',m).onclick=()=>downloadCSV([['Item','Width cm','Depth cm','Price','Notes'],...objects().filter(o=>o.owned===false).map(o=>[o.name,o.w,o.h,o.price||'',o.notes||''])],`${slug(currentRoom().name)}-shopping-list.csv`);$('#expSummary',m).onclick=copySummary})}
function exportPNG(){const svg=$('#planCanvas'),copy=svg.cloneNode(true);copy.setAttribute('xmlns',SVG_NS);const xml=new XMLSerializer().serializeToString(copy),blob=new Blob([xml],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{const vb=(svg.getAttribute('viewBox')||'0 0 800 600').split(/\s+/).map(Number),ratio=vb[2]/vb[3],c=document.createElement('canvas');c.width=1600;c.height=Math.round(1600/ratio);const ctx=c.getContext('2d');ctx.fillStyle='#fffafa';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);c.toBlob(b=>{downloadBlob(b,`${slug(currentRoom().name)}-${slug(currentLayout().name)}.png`,'image/png');URL.revokeObjectURL(url)},'image/png')};img.onerror=()=>{URL.revokeObjectURL(url);toast('PNG export failed')};img.src=url}
