function downloadCSV(rows,name){const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');downloadBlob(csv,name,'text/csv')}
async function copySummary(){const r=currentRoom(),l=currentLayout(),m=layoutMetrics(l);copyText(`${r.name}\nRoom: ${display(r.width,r.unit)} × ${display(r.height,r.unit)}\nLayout: ${l.name}\nObjects: ${m.items}\nDango Fit score: ${m.score}\nIssues: ${m.issues}\nApprox. floor footprint: ${m.occupied.toFixed(1)}%`)}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied')}catch{prompt('Copy:',text)}}
function downloadBlob(blob,name,type){const b=blob instanceof Blob?blob:new Blob([blob],{type}),a=document.createElement('a'),url=URL.createObjectURL(b);a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}


