function smartSnap(o,x,y,disable=false){if(disable)return{x,y,snapped:false};const r=currentRoom(),s=Math.max(1,state.settings.snapSize||10),tol=Math.max(6,s*.8);let snapped=false;if(state.settings.snap){const nx=Math.round(x/s)*s,ny=Math.round(y/s)*s;snapped=snapped||Math.abs(nx-x)>.01||Math.abs(ny-y)>.01;x=nx;y=ny}if(state.settings.wallSnap&&r.shapeType==='rectangle'){if(Math.abs(x)<tol){x=0;snapped=true}if(Math.abs(y)<tol){y=0;snapped=true}if(Math.abs(x+o.w-r.width)<tol){x=r.width-o.w;snapped=true}if(Math.abs(y+o.h-r.height)<tol){y=r.height-o.h;snapped=true}}if(state.settings.objectSnap){const candidatesX=[r.width/2-o.w/2],candidatesY=[r.height/2-o.h/2];objects().filter(a=>a.id!==o.id&&!a.hidden&&a.type!=='zone').forEach(a=>{candidatesX.push(a.x,a.x+a.w,a.x-o.w,a.x+a.w-o.w,(a.x+a.w/2)-o.w/2);candidatesY.push(a.y,a.y+a.h,a.y-o.h,a.y+a.h-o.h,(a.y+a.h/2)-o.h/2)});let bestX=null,bestDX=Infinity,bestY=null,bestDY=Infinity;for(const v of candidatesX){const d=Math.abs(x-v);if(d<tol&&d<bestDX){bestDX=d;bestX=v}}for(const v of candidatesY){const d=Math.abs(y-v);if(d<tol&&d<bestDY){bestDY=d;bestY=v}}if(bestX!==null){x=bestX;snapped=true}if(bestY!==null){y=bestY;snapped=true}}return{x,y,snapped}}
function objectPointerDown(e){e.stopPropagation();if(state.activeTool==='measure'){handleMeasureTap(e);return}const id=e.currentTarget.dataset.id,o=objects().find(x=>x.id===id);if(!o)return;if(o.locked)return toast('Object is locked');state.selectedId=id;const p=svgPoint(e),g=planGeometry(),co=objectCoords(o,g),group=o.groupId?objects().filter(x=>x.groupId===o.groupId&&!x.locked):[o];drag={id,startX:p.x,startY:p.y,origX:o.x,origY:o.y,lastX:o.x,lastY:o.y,element:e.currentTarget,baseTransform:e.currentTarget.getAttribute('transform')||'',g,centerX:co.x+co.w/2,centerY:co.y+co.h/2,moved:false,pointerId:e.pointerId,snapDisabled:e.altKey||e.shiftKey,lastSnap:false,group:group.map(item=>({id:item.id,origX:item.x,origY:item.y,element:$(`[data-id="${item.id}"]`),baseTransform:$(`[data-id="${item.id}"]`)?.getAttribute('transform')||''}))};drag.snapTimer=setTimeout(()=>{if(drag&&!drag.moved&&!drag.snapDisabled){drag.snapDisabled=true;drag.holdArmed=true;haptic(7)}},380);drag.toolsTimer=setTimeout(()=>{if(drag&&!drag.moved){const target=drag.id;haptic(12);objectPointerUp();selectedToolsModal(target)}},780);document.body.classList.add('dragging');e.currentTarget.setPointerCapture?.(e.pointerId);window.addEventListener('pointermove',objectPointerMove,{passive:false});window.addEventListener('pointerup',objectPointerUp,{once:true});window.addEventListener('pointercancel',objectPointerUp,{once:true})}
