function rectDistance(a,b){const A=objectBounds(a),B=objectBounds(b),dx=Math.max(B.x-(A.x+A.w),A.x-(B.x+B.w),0),dy=Math.max(B.y-(A.y+A.h),A.y-(B.y+B.h),0);return Math.hypot(dx,dy)}
