function roomSettingsModal(){const r=currentRoom();if(!r)return;const u=r.unit;modal('Room settings',`<form id="roomSettingsForm" class="form-grid"><div class="field full"><label>Room name</label><input name="name" value="${attr(r.name)}"></div><div class="field"><label>Bounding width (${u})</label><input type="number" step="0.1" name="width" value="${unitInput(r.width,u)}" ${r.shapeType!=='rectangle'?'disabled':''}></div><div class="field"><label>Bounding length (${u})</label><input type="number" step="0.1" name="height" value="${unitInput(r.height,u)}" ${r.shapeType!=='rectangle'?'disabled':''}></div><div class="field"><label>Display unit</label><select name="unit">${Object.keys(UNIT).map(k=>`<option ${k===u?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label>Ceiling height (${u})</label><input type="number" step="0.1" name="ceilingHeight" value="${r.ceilingHeight?unitInput(r.ceilingHeight,u):''}" placeholder="Optional"></div><div class="field full"><label>Room type</label><input name="roomType" value="${attr(r.roomType||'Room')}"></div><div class="field full"><label>Room notes</label><textarea name="notes" rows="4">${esc(r.notes||'')}</textarea></div><div class="form-actions field full"><button type="button" class="secondary-btn" id="editShape">Walls & shape</button><button class="primary-btn">Save room</button></div></form>`,m=>{$('#editShape',m).onclick=()=>{m.remove();roomShapeModal()};$('form',m).onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));snapshot('Edit room settings');if(r.shapeType==='rectangle'){const nw=Math.max(100,toCm(d.width,u)),nh=Math.max(100,toCm(d.height,u));r.width=nw;r.height=nh;r.points=normalizeRoomPoints(null,nw,nh);r.layouts.forEach(l=>l.objects.forEach(o=>{if((o.type==='door'||o.type==='window')&&o.wall){const width=Math.max(o.w,o.h),oldOff=(o.wall==='top'||o.wall==='bottom')?o.x:o.y;positionWallOpeningForRoom(o,r,o.wall,width,oldOff)}else normalizeWithinRoomForRoom(o,r)}))}r.name=d.name||r.name;r.unit=d.unit;r.ceilingHeight=toCm(d.ceilingHeight,u);r.roomType=d.roomType||r.roomType;r.notes=d.notes;r.updatedAt=now();persist();m.remove();renderAll();toast('Room updated')}})}

function editObjectModal(id){const o=objects().find(x=>x.id===id);if(!o)return;if(o.type==='door')return editDoorModal(o);if(o.type==='window')return editWindowModal(o);const u=rUnit();modal(`Edit ${o.name}`,`<form id="editObjectForm" class="form-grid"><div class="field full"><label>Label</label><input name="name" value="${attr(o.name)}"></div><div class="field"><label>Width (${u})</label><input type="number" step="0.1" name="w" value="${unitInput(o.w,u)}"></div><div class="field"><label>Depth (${u})</label><input type="number" step="0.1" name="h" value="${unitInput(o.h,u)}"></div><div class="field"><label>Height (${u})</label><input type="number" step="0.1" name="height" value="${o.height?unitInput(o.height,u):''}" placeholder="Optional"></div><div class="field"><label>Rotation</label><input type="number" name="rotation" value="${o.rotation||0}" step="1"></div><div class="field"><label>X from left (${u})</label><input type="number" step="0.1" name="x" value="${unitInput(o.x,u)}"></div><div class="field"><label>Y from top (${u})</label><input type="number" step="0.1" name="y" value="${unitInput(o.y,u)}"></div><div class="field"><label>Clearance (${u})</label><input type="number" name="clearance" value="${unitInput(o.clearance||0,u)}" step="0.1"></div><div class="field"><label>Cable reach (${u})</label><input type="number" name="cableLength" value="${o.cableLength?unitInput(o.cableLength,u):''}" step="0.1"></div><div class="field"><label>Alternate width (${u})</label><input type="number" name="altW" value="${o.altW?unitInput(o.altW,u):''}" step="0.1"></div><div class="field"><label>Alternate depth (${u})</label><input type="number" name="altH" value="${o.altH?unitInput(o.altH,u):''}" step="0.1"></div><div class="field"><label>Measurement</label><select name="measureConfidence"><option value="exact" ${o.measureConfidence==='exact'?'selected':''}>Exact</option><option value="approx" ${o.measureConfidence==='approx'?'selected':''}>Approximate</option><option value="remeasure" ${o.measureConfidence==='remeasure'?'selected':''}>Need to re-measure</option></select></div><div class="field"><label>Ownership</label><select name="owned"><option value="true" ${o.owned!==false?'selected':''}>Owned</option><option value="false" ${o.owned===false?'selected':''}>Considering / To buy</option></select></div><div class="field"><label>Moving status</label><select name="moveStatus">${MOVING_STATUSES.map(s=>`<option ${s===o.moveStatus?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Price</label><input type="number" name="price" value="${o.price||''}" min="0" step="0.01" placeholder="Optional"></div><div class="field"><label>Color</label><input type="color" name="color" value="${o.color||'#f1c8d4'}"></div><div class="field full"><label>Tags (comma separated)</label><input name="tags" value="${attr((o.tags||[]).join(', '))}" placeholder="must keep, work, storage"></div><div class="field full"><label>Notes</label><textarea name="notes" rows="3">${esc(o.notes||'')}</textarea></div><div class="form-actions field full"><button type="button" class="secondary-btn cancel">Cancel</button><button class="primary-btn">Save changes</button></div></form>`,m=>{$('.cancel',m).onclick=()=>m.remove();$('form',m).onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));snapshot('Edit object');Object.assign(o,{name:d.name||o.name,w:Math.max(1,toCm(d.w,u)),h:Math.max(1,toCm(d.h,u)),height:toCm(d.height,u),x:toCm(d.x,u),y:toCm(d.y,u),rotation:Number(d.rotation)||0,clearance:toCm(d.clearance,u),cableLength:toCm(d.cableLength,u),altW:toCm(d.altW,u),altH:toCm(d.altH,u),color:d.color,measureConfidence:d.measureConfidence,owned:d.owned==='true',moveStatus:d.moveStatus,price:Number(d.price)||0,tags:String(d.tags||'').split(',').map(x=>x.trim()).filter(Boolean),notes:d.notes});currentLayout().updatedAt=now();persist();m.remove();renderPlan(true)}})}
function addWindowModal(){if(!currentRoom())return newRoomModal();const u=rUnit();modal('Add window',`<form id="windowForm" class="form-grid"><div class="field"><label>Width (${u})</label><input type="number" name="width" value="${unitInput(120,u)}" step="0.1"></div><div class="field"><label>Wall</label><select name="wall"><option>top</option><option>right</option><option>bottom</option><option>left</option></select></div><div class="field"><label>Window type</label><select name="kind"><option value="fixed">Fixed</option><option value="sliding">Sliding</option><option value="casement">Casement</option></select></div><div class="field"><label>Sill height (${u})</label><input type="number" name="sillHeight" placeholder="Optional"></div><div class="field"><label>Window height (${u})</label><input type="number" name="openingHeight" placeholder="Optional"></div><div class="field"><label>Opening clearance (${u})</label><input type="number" name="clearance" value="${unitInput(45,u)}" step="0.1"></div><div class="field full"><label>Offset from wall start (${u})</label><input type="number" name="offset" value="${unitInput(60,u)}" step="0.1"></div><div class="form-actions field full"><button type="button" class="secondary-btn cancel">Cancel</button><button class="primary-btn">Add window</button></div></form>`,m=>{$('.cancel',m).onclick=()=>m.remove();$('form',m).onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),r=currentRoom(),w=Math.max(30,toCm(d.width,u)),off=toCm(d.offset,u);snapshot('Add window');let o=normalizeObject({id:uid('obj'),type:'window',name:'Window',w,h:8,x:0,y:0,rotation:0,color:'#cbe5ea',wall:d.wall,kind:d.kind,locked:false,clearance:toCm(d.clearance,u),sillHeight:toCm(d.sillHeight,u),openingHeight:toCm(d.openingHeight,u)});positionWallOpening(o,d.wall,w,off);objects().push(o);state.selectedId=o.id;persist();m.remove();renderPlan(true);toast('Window added')}})}
function editWindowModal(o){const u=rUnit(),width=Math.max(o.w,o.h),off=wallOffset(o);modal('Edit window',`<form id="editWindowForm" class="form-grid"><div class="field"><label>Width (${u})</label><input name="width" type="number" value="${unitInput(width,u)}" step="0.1"></div><div class="field"><label>Wall</label><select name="wall">${['top','right','bottom','left'].map(x=>`<option ${x===o.wall?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Window type</label><select name="kind"><option value="fixed" ${o.kind==='fixed'?'selected':''}>Fixed</option><option value="sliding" ${o.kind==='sliding'?'selected':''}>Sliding</option><option value="casement" ${o.kind==='casement'?'selected':''}>Casement</option></select></div><div class="field"><label>Sill height (${u})</label><input name="sillHeight" type="number" value="${o.sillHeight?unitInput(o.sillHeight,u):''}" placeholder="Optional"></div><div class="field"><label>Window height (${u})</label><input name="openingHeight" type="number" value="${o.openingHeight?unitInput(o.openingHeight,u):''}" placeholder="Optional"></div><div class="field"><label>Opening clearance (${u})</label><input name="clearance" type="number" value="${unitInput(o.clearance||0,u)}" step="0.1"></div><div class="field full"><label>Offset (${u})</label><input name="offset" type="number" value="${unitInput(off,u)}" step="0.1"></div><div class="form-actions field full"><button type="button" class="secondary-btn cancel">Cancel</button><button class="primary-btn">Save</button></div></form>`,m=>{$('.cancel',m).onclick=()=>m.remove();$('form',m).onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));snapshot('Edit window');positionWallOpening(o,d.wall,Math.max(30,toCm(d.width,u)),toCm(d.offset,u));Object.assign(o,{kind:d.kind,clearance:toCm(d.clearance,u),sillHeight:toCm(d.sillHeight,u),openingHeight:toCm(d.openingHeight,u)});persist();m.remove();renderPlan(true)}})}
function addDoorModal(){if(!currentRoom())return newRoomModal();const u=rUnit();modal('Add door',`<form id="doorForm" class="form-grid"><div class="field"><label>Width (${u})</label><input type="number" name="width" value="${unitInput(90,u)}" step="0.1"></div><div class="field"><label>Door height (${u})</label><input type="number" name="doorHeight" placeholder="Optional"></div><div class="field"><label>Wall</label><select name="wall"><option>top</option><option>right</option><option>bottom</option><option>left</option></select></div><div class="field"><label>Door type</label><select name="kind"><option value="hinged">Hinged</option><option value="sliding">Sliding</option><option value="pocket">Pocket</option></select></div><div class="field"><label>Hinge side</label><select name="hinge"><option value="left">Left</option><option value="right">Right</option></select></div><div class="field"><label>Open direction</label><select name="swing"><option value="inward">Inward</option><option value="outward">Outward</option></select></div><div class="field full"><label>Offset from wall start (${u})</label><input type="number" name="offset" value="${unitInput(30,u)}" step="0.1"></div><div class="form-actions field full"><button type="button" class="secondary-btn cancel">Cancel</button><button class="primary-btn">Add door</button></div></form>`,m=>{$('.cancel',m).onclick=()=>m.remove();$('form',m).onsubmit=e=>{e.preventDefault();addDoor(Object.fromEntries(new FormData(e.target)));m.remove()}})}
function addDoor(d){snapshot('Add door');const r=currentRoom(),width=Math.max(30,toCm(d.width,rUnit())),off=toCm(d.offset,rUnit());let o=normalizeObject({id:uid('obj'),type:'door',name:'Door',w:width,h:4,rotation:0,color:'#f7a8bd',hinge:d.hinge,swing:d.swing,kind:d.kind||'hinged',wall:d.wall,clearance:width,doorHeight:toCm(d.doorHeight,rUnit()),locked:false});positionWallOpening(o,d.wall,width,off);objects().push(o);state.selectedId=o.id;persist();renderPlan(true);toast('Door added')}
function editDoorModal(o){const u=rUnit(),width=Math.max(o.w,o.h),off=wallOffset(o);modal('Edit door',`<form id="editDoorForm" class="form-grid"><div class="field"><label>Width (${u})</label><input name="width" type="number" value="${unitInput(width,u)}" step="0.1"></div><div class="field"><label>Door height (${u})</label><input name="doorHeight" type="number" value="${o.doorHeight?unitInput(o.doorHeight,u):''}" placeholder="Optional"></div><div class="field"><label>Wall</label><select name="wall">${['top','right','bottom','left'].map(x=>`<option ${x===o.wall?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Door type</label><select name="kind"><option value="hinged" ${o.kind==='hinged'?'selected':''}>Hinged</option><option value="sliding" ${o.kind==='sliding'?'selected':''}>Sliding</option><option value="pocket" ${o.kind==='pocket'?'selected':''}>Pocket</option></select></div><div class="field"><label>Hinge</label><select name="hinge"><option value="left" ${o.hinge==='left'?'selected':''}>Left</option><option value="right" ${o.hinge==='right'?'selected':''}>Right</option></select></div><div class="field"><label>Swing</label><select name="swing"><option value="inward" ${o.swing==='inward'?'selected':''}>Inward</option><option value="outward" ${o.swing==='outward'?'selected':''}>Outward</option></select></div><div class="field"><label>Offset (${u})</label><input name="offset" type="number" value="${unitInput(off,u)}" step="0.1"></div><div class="form-actions field full"><button type="button" class="secondary-btn cancel">Cancel</button><button class="primary-btn">Save</button></div></form>`,m=>{$('.cancel',m).onclick=()=>m.remove();$('form',m).onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));snapshot('Edit door');const w=Math.max(30,toCm(d.width,u));positionWallOpening(o,d.wall,w,toCm(d.offset,u));Object.assign(o,{kind:d.kind,hinge:d.hinge,swing:d.swing,clearance:w,doorHeight:toCm(d.doorHeight,u)});persist();m.remove();renderPlan(true)}})}

function renderSelectionTray(){let tray=$('#selectionTray');if(!tray){tray=document.createElement('div');tray.id='selectionTray';tray.className='selection-tray';$('#canvasWrap').appendChild(tray)}const o=objects().find(x=>x.id===state.selectedId);if(!o){tray.style.display='none';return}tray.style.display='flex';tray.innerHTML=`<button class="tiny-btn" data-sel="edit" title="Edit">✏️</button><button class="tiny-btn" data-sel="rotate" title="Rotate">↻</button><button class="tiny-btn" data-sel="duplicate" title="Duplicate">⧉</button><button class="tiny-btn" data-sel="copy" title="Copy">⧉</button><button class="tiny-btn" data-sel="tools" title="Smart tools">✨</button><button class="tiny-btn" data-sel="lock" title="Lock">${o.locked?'🔒':'🔓'}</button><button class="tiny-btn" data-sel="delete" title="Delete">🗑️</button>`;$$('button',tray).forEach(b=>b.onclick=()=>selectionAction(b.dataset.sel,o.id))}
function selectionAction(a,id){const o=objects().find(x=>x.id===id);if(!o)return;if(a==='edit')return editObjectModal(id);if(a==='tools')return selectedToolsModal(id);if(a==='copy'){state.clipboard=deepClone(o);toast('Copied object');return}if(a==='rotate'&&['door','window'].includes(o.type))return toast('Doors and windows stay aligned to their wall');if(a==='delete'&&state.settings.confirmDelete&&!confirm(`Delete “${o.name}”?`))return;snapshot(a==='rotate'?'Rotate object':a==='duplicate'?'Duplicate object':a==='delete'?'Delete object':'Change object');if(a==='rotate'){o.rotation=((o.rotation||0)+90)%360;haptic(6)}else if(a==='duplicate'){const cp=deepClone(o);cp.id=uid('obj');cp.name=`${o.name} Copy`;if(['door','window'].includes(cp.type)){const width=Math.max(cp.w,cp.h),off=wallOffset(cp)+15;positionWallOpening(cp,cp.wall,width,off)}else{cp.x+=15;cp.y+=15}objects().push(cp);state.selectedId=cp.id}else if(a==='lock')o.locked=!o.locked;else if(a==='delete'){const group=o.groupId?objects().filter(x=>x.groupId===o.groupId):[o];group.forEach(g=>{const i=objects().findIndex(x=>x.id===g.id);if(i>=0)objects().splice(i,1)});state.selectedId=null}currentLayout().updatedAt=now();persist();renderPlan(true)}
function pasteClipboard(){if(!state.clipboard||!currentRoom())return toast('Copy an object first');snapshot('Paste object');const o=normalizeObject(deepClone(state.clipboard));o.id=uid('obj');o.x=clamp((Number(o.x)||0)+20,0,Math.max(0,currentRoom().width-o.w));o.y=clamp((Number(o.y)||0)+20,0,Math.max(0,currentRoom().height-o.h));o.groupId=null;objects().push(o);state.selectedId=o.id;persist();renderPlan(true);toast('Pasted object')}
function objectListModal(){const arr=objects();state.multiSelectedIds=[];modal('Objects in this layout',arr.length?`<div class="field"><input id="objListSearch" placeholder="Search objects…"></div><div class="form-actions"><button class="secondary-btn" id="groupSelected">Group selected</button><button class="secondary-btn" id="ungroupSelected">Ungroup</button><button class="secondary-btn" id="alignSelected">Align</button><button class="secondary-btn" id="pasteObject">Paste</button></div><div class="list" id="objListRows"></div>`:`<div class="empty-state"><div class="big">🪑</div><h3>No objects yet</h3><p>Add only the furniture and fixtures that belong in this room.</p></div>`,m=>{const draw=()=>{const q=$('#objListSearch',m)?.value.toLowerCase()||'';$('#objListRows',m).innerHTML=arr.filter(o=>o.name.toLowerCase().includes(q)).map(o=>`<div class="list-row"><input type="checkbox" class="multi-check" data-multi="${o.id}" ${state.multiSelectedIds.includes(o.id)?'checked':''}><button class="plain-select" data-select="${o.id}"><b>${esc(o.name)}</b><span class="meta">${o.type}${o.groupId?' • grouped':''} • ${display(o.w,rUnit())} × ${display(o.h,rUnit())}</span></button><div class="row-actions"><button class="tiny-btn" data-hide="${o.id}">${o.hidden?'👁':'🙈'}</button><button class="tiny-btn" data-lock="${o.id}">${o.locked?'🔒':'🔓'}</button></div></div>`).join('');$$('[data-multi]',m).forEach(c=>c.onchange=()=>{state.multiSelectedIds=c.checked?[...new Set([...state.multiSelectedIds,c.dataset.multi])]:state.multiSelectedIds.filter(x=>x!==c.dataset.multi)});$$('[data-select]',m).forEach(b=>b.onclick=()=>{state.selectedId=b.dataset.select;m.remove();renderPlan()});$$('[data-hide]',m).forEach(b=>b.onclick=()=>{const o=arr.find(x=>x.id===b.dataset.hide);o.hidden=!o.hidden;persist();draw();renderPlan(true)});$$('[data-lock]',m).forEach(b=>b.onclick=()=>{const o=arr.find(x=>x.id===b.dataset.lock);o.locked=!o.locked;persist();draw();renderPlan()})};$('#objListSearch',m)?.addEventListener('input',draw);$('#groupSelected',m).onclick=()=>{if(state.multiSelectedIds.length<2)return toast('Select at least two objects');snapshot('Group objects');const gid=uid('group');arr.filter(o=>state.multiSelectedIds.includes(o.id)).forEach(o=>o.groupId=gid);persist();draw();renderPlan();toast('Objects grouped')};$('#ungroupSelected',m).onclick=()=>{if(!state.multiSelectedIds.length)return toast('Select objects to ungroup');snapshot('Ungroup objects');arr.filter(o=>state.multiSelectedIds.includes(o.id)).forEach(o=>o.groupId=null);persist();draw();renderPlan();toast('Objects ungrouped')};$('#alignSelected',m).onclick=()=>{m.remove();alignSelectedModal()};$('#pasteObject',m).onclick=()=>{m.remove();pasteClipboard()};draw()})}

function primaryLayoutForRoom(r){if(r.id===state.currentRoomId)return r.layouts.find(l=>l.id===state.currentLayoutId)||r.layouts[0];return r.layouts.find(l=>l.favorite)||r.layouts[0]}
function wholeHomeItems(){return state.rooms.flatMap(r=>{const l=primaryLayoutForRoom(r);return(l?.objects||[]).filter(o=>o.type==='furniture').map(o=>({room:r,layout:l,o}))})}
function wholeHomeModal(){const items=wholeHomeItems(),buy=items.filter(x=>x.o.owned===false),placed=items.filter(x=>x.o.moveStatus==='Placed').length;modal(state.homeName||'Whole home',`<div class="metrics-grid"><div class="metric-card"><b>${state.rooms.length}</b><span>Rooms</span></div><div class="metric-card"><b>${items.length}</b><span>Furniture items</span></div><div class="metric-card"><b>${buy.length}</b><span>To buy</span></div><div class="metric-card"><b>${placed}/${items.length}</b><span>Placed</span></div></div><div class="field"><label>Home / project name</label><input id="homeNameInput" value="${attr(state.homeName)}" placeholder="Optional, e.g. New apartment"></div><div class="field"><input id="homeSearch" placeholder="Search furniture across rooms…"></div><div class="list" id="homeRows"></div>`,m=>{const draw=()=>{const q=$('#homeSearch',m).value.toLowerCase();$('#homeRows',m).innerHTML=items.filter(x=>x.o.name.toLowerCase().includes(q)||x.room.name.toLowerCase().includes(q)).slice(0,100).map(({room,o})=>`<div class="list-row"><span><b>${esc(o.name)}</b><span class="meta">${esc(room.name)} • ${o.moveStatus}</span></span><button class="tiny-btn" data-movehome="${room.id}|${o.id}">Move room</button></div>`).join('')||'<p class="help">No matching furniture.</p>';$$('[data-movehome]',m).forEach(b=>b.onclick=()=>{const [rid,oid]=b.dataset.movehome.split('|');m.remove();moveItemRoomModal(rid,oid)})};$('#homeNameInput',m).onchange=e=>{state.homeName=e.target.value.trim();persist()};$('#homeSearch',m).oninput=draw;draw()})}
function moveItemRoomModal(sourceRoomId,objId){const src=state.rooms.find(r=>r.id===sourceRoomId),sl=src&&primaryLayoutForRoom(src),o=sl?.objects.find(x=>x.id===objId);if(!o)return;const targets=state.rooms.filter(r=>r.id!==sourceRoomId);if(!targets.length)return toast('Create another room first');modal(`Move ${o.name}`,`<div class="list">${targets.map(r=>`<button class="list-row" data-target="${r.id}"><span>${esc(r.name)}</span><span>›</span></button>`).join('')}</div>`,m=>$$('[data-target]',m).forEach(b=>b.onclick=()=>{const target=state.rooms.find(r=>r.id===b.dataset.target),tl=primaryLayoutForRoom(target);snapshot('Move item between rooms');sl.objects=sl.objects.filter(x=>x.id!==o.id);issueCache.delete(sl);issueCache.delete(tl);o.x=Math.max(0,target.width/2-o.w/2);o.y=Math.max(0,target.height/2-o.h/2);o.groupId=null;tl.objects.push(o);persist();m.remove();renderAll();toast(`Moved to ${target.name}`)}))}
function movingModeModal(){const items=wholeHomeItems(),counts=Object.fromEntries(MOVING_STATUSES.map(s=>[s,items.filter(x=>x.o.moveStatus===s).length]));modal('Moving mode',`<div class="moving-status-grid">${MOVING_STATUSES.map(s=>`<button data-filterstatus="${s}"><b>${counts[s]}</b><span>${s}</span></button>`).join('')}</div><div class="list"><button class="list-row" id="movingItems"><span>📦 Furniture moving status</span><span>${items.length}</span></button><button class="list-row" id="movingBoxes"><span>🏷 Moving boxes & labels</span><span>${state.movingBoxes.length}</span></button><button class="list-row" id="movingAccess"><span>🚪 Access measurements</span><span>Entrance, hall, lift</span></button><button class="list-row" id="movingExport"><span>⬇️ Export moving list</span><span>CSV</span></button></div>`,m=>{$('#movingItems',m).onclick=()=>{m.remove();movingItemsModal()};$('#movingBoxes',m).onclick=()=>{m.remove();movingBoxesModal()};$('#movingAccess',m).onclick=()=>{m.remove();movingAccessModal()};$('#movingExport',m).onclick=()=>downloadCSV([['Room','Item','Status','Width cm','Depth cm','Notes'],...items.map(x=>[x.room.name,x.o.name,x.o.moveStatus,x.o.w,x.o.h,x.o.notes||''])],'dango-moving-list.csv');$$('[data-filterstatus]',m).forEach(b=>b.onclick=()=>{m.remove();movingItemsModal(b.dataset.filterstatus)})})}
function movingItemsModal(filter=''){const items=wholeHomeItems().filter(x=>!filter||x.o.moveStatus===filter);modal(filter?`Moving — ${filter}`:'Furniture moving status',`<div class="list">${items.map(({room,o})=>`<button class="list-row" data-moveitem="${room.id}|${o.id}"><span><b>${esc(o.name)}</b><span class="meta">${esc(room.name)}</span></span><span>${esc(o.moveStatus)} ›</span></button>`).join('')||'<p class="help">No items in this status.</p>'}</div>`,m=>$$('[data-moveitem]',m).forEach(b=>b.onclick=()=>{const [rid,oid]=b.dataset.moveitem.split('|'),room=state.rooms.find(r=>r.id===rid),o=primaryLayoutForRoom(room)?.objects.find(x=>x.id===oid);if(!o)return;m.remove();modal(`Moving status — ${o.name}`,`<div class="list">${MOVING_STATUSES.map(s=>`<button class="list-row" data-setstatus="${s}"><span>${s}</span><span>${s===o.moveStatus?'✓':''}</span></button>`).join('')}</div>`,mm=>$$('[data-setstatus]',mm).forEach(x=>x.onclick=()=>{snapshot('Update moving status');o.moveStatus=x.dataset.setstatus;persist();mm.remove();movingItemsModal(filter);toast('Moving status updated')}))}))}
function movingBoxesModal(){modal('Moving boxes',`<div class="form-actions"><button class="primary-btn" id="addMovingBox">＋ Add box</button><button class="secondary-btn" id="exportBoxLabels">Export labels</button></div><div class="list">${state.movingBoxes.map(b=>{const r=state.rooms.find(x=>x.id===b.destinationRoomId);return `<button class="list-row" data-box="${b.id}"><span><b>${esc(b.label)}</b><span class="meta">${esc(r?.name||'No room assigned')} • ${esc(b.contents||'No contents note')}</span></span><span>${esc(b.status)} ›</span></button>`}).join('')||'<p class="help">No moving boxes yet. Add only the boxes you actually pack.</p>'}</div>`,m=>{$('#addMovingBox',m).onclick=()=>{m.remove();editMovingBoxModal()};$('#exportBoxLabels',m).onclick=()=>downloadCSV([['Box','Destination room','Contents','Status'],...state.movingBoxes.map(b=>[b.label,state.rooms.find(r=>r.id===b.destinationRoomId)?.name||'',b.contents,b.status])],'dango-box-labels.csv');$$('[data-box]',m).forEach(b=>b.onclick=()=>{m.remove();editMovingBoxModal(b.dataset.box)})})}
function editMovingBoxModal(id=''){const box=state.movingBoxes.find(b=>b.id===id)||{id:'',label:'',destinationRoomId:'',contents:'',status:'Keeping'};modal(id?'Edit moving box':'Add moving box',`<form id="boxForm"><div class="field"><label>Box label</label><input name="label" value="${attr(box.label)}" placeholder="e.g. Bedroom 01" required></div><div class="field"><label>Destination room</label><select name="destinationRoomId"><option value="">Not assigned</option>${state.rooms.map(r=>`<option value="${r.id}" ${r.id===box.destinationRoomId?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="field"><label>Contents</label><textarea name="contents" rows="3" placeholder="Optional contents note">${esc(box.contents)}</textarea></div><div class="field"><label>Status</label><select name="status">${MOVING_STATUSES.map(s=>`<option ${s===box.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="form-actions">${id?'<button type="button" class="secondary-btn" id="deleteBox">Delete</button>':''}<button class="primary-btn">Save box</button></div></form>`,m=>{$('#deleteBox',m)?.addEventListener('click',()=>{snapshot('Delete moving box');state.movingBoxes=state.movingBoxes.filter(b=>b.id!==id);persist();m.remove();movingBoxesModal()});$('form',m).onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));snapshot(id?'Edit moving box':'Add moving box');if(id)Object.assign(box,d);else state.movingBoxes.push({id:uid('box'),...d});persist();m.remove();movingBoxesModal();toast('Box saved')}})}

function settingsModal(){const s=state.settings;modal('Settings',`<div class="field"><label>Theme</label><select id="settingTheme"><option value="pink" ${s.theme==='pink'?'selected':''}>Dango pink</option><option value="lavender" ${s.theme==='lavender'?'selected':''}>Lavender</option><option value="peach" ${s.theme==='peach'?'selected':''}>Peach</option><option value="sage" ${s.theme==='sage'?'selected':''}>Sage</option><option value="cream" ${s.theme==='cream'?'selected':''}>Cream</option></select></div><div class="field"><label>Default display unit</label><select id="settingUnit">${Object.keys(UNIT).map(k=>`<option value="${k}" ${k===s.unit?'selected':''}>${UNIT[k].label}</option>`).join('')}</select></div><div class="field"><label>Performance</label><select id="settingPerformance"><option value="auto" ${s.performanceMode==='auto'?'selected':''}>Automatic — recommended</option><option value="performance" ${s.performanceMode==='performance'?'selected':''}>Smoothness first</option><option value="detail" ${s.performanceMode==='detail'?'selected':''}>Visual detail first</option></select></div><div class="field"><label>Startup screen</label><select id="settingStartup"><option value="rooms" ${s.startupView!=='last'?'selected':''}>Rooms</option><option value="last" ${s.startupView==='last'?'selected':''}>Last open plan</option></select></div><div class="field"><label>Minimum preferred walkway (cm)</label><input type="number" id="settingWalkway" value="${s.minimumWalkway}" min="20" max="200"></div><div class="switch-row"><span>Grid</span><input type="checkbox" class="switch" id="settingGrid" ${s.grid?'checked':''}></div><div class="switch-row"><span>Snap to grid</span><input type="checkbox" class="switch" id="settingSnap" ${s.snap?'checked':''}></div><div class="switch-row"><span>Snap to walls</span><input type="checkbox" class="switch" id="settingWallSnap" ${s.wallSnap?'checked':''}></div><div class="switch-row"><span>Snap to other objects</span><input type="checkbox" class="switch" id="settingObjectSnap" ${s.objectSnap?'checked':''}></div><div class="switch-row"><span>Snap haptics</span><input type="checkbox" class="switch" id="settingSnapHaptics" ${s.snapHaptics?'checked':''}></div><div class="field"><label>Snap size (cm)</label><input type="number" id="settingSnapSize" value="${s.snapSize}" min="1" max="100"></div><div class="switch-row"><span>Precision HUD</span><input type="checkbox" class="switch" id="settingPrecisionHud" ${s.precisionHud?'checked':''}></div><div class="switch-row"><span>Show Fit status on plan</span><input type="checkbox" class="switch" id="settingFitStatus" ${s.showFitStatus?'checked':''}></div><div class="switch-row"><span>Show issue count on plan</span><input type="checkbox" class="switch" id="settingIssueStatus" ${s.showIssueStatus?'checked':''}></div><div class="switch-row"><span>Haptics</span><input type="checkbox" class="switch" id="settingHaptics" ${s.haptics?'checked':''}></div><div class="switch-row"><span>Confirm before deleting</span><input type="checkbox" class="switch" id="settingConfirmDelete" ${s.confirmDelete?'checked':''}></div><div class="switch-row"><span>Reduce motion</span><input type="checkbox" class="switch" id="settingReduceMotion" ${s.reduceMotion?'checked':''}></div><div class="form-actions"><button class="secondary-btn" id="showOnboarding">Show getting started</button><button class="primary-btn" id="saveSettings">Save settings</button></div>`,m=>{$('#showOnboarding',m).onclick=()=>{m.remove();onboardingModal(false)};$('#saveSettings',m).onclick=()=>{Object.assign(state.settings,{theme:$('#settingTheme',m).value,unit:$('#settingUnit',m).value,performanceMode:$('#settingPerformance',m).value,startupView:$('#settingStartup',m).value,grid:$('#settingGrid',m).checked,snap:$('#settingSnap',m).checked,wallSnap:$('#settingWallSnap',m).checked,objectSnap:$('#settingObjectSnap',m).checked,snapHaptics:$('#settingSnapHaptics',m).checked,snapSize:clamp(Number($('#settingSnapSize',m).value)||10,1,100),minimumWalkway:clamp(Number($('#settingWalkway',m).value)||70,20,200),precisionHud:$('#settingPrecisionHud',m).checked,showFitStatus:$('#settingFitStatus',m).checked,showIssueStatus:$('#settingIssueStatus',m).checked,haptics:$('#settingHaptics',m).checked,confirmDelete:$('#settingConfirmDelete',m).checked,reduceMotion:$('#settingReduceMotion',m).checked});state.settings.workspaceMode='custom';applyAppearance();persist();m.remove();renderAll();toast('Settings saved')}})}
function storageHealthModal(){let bytes=0;try{bytes=new Blob([localStorage.getItem(STORAGE_KEY)||'']).size}catch{}const kb=bytes/1024,historyCount=state.history.length+state.future.length;modal('Storage health',`<div class="metrics-grid"><div class="metric-card"><b>${kb<1024?kb.toFixed(0)+' KB':(kb/1024).toFixed(2)+' MB'}</b><span>Primary saved data</span></div><div class="metric-card"><b>${state.rooms.length}</b><span>Rooms</span></div><div class="metric-card"><b>${state.library.length}</b><span>My Objects</span></div><div class="metric-card"><b>${historyCount}</b><span>Undo states in memory</span></div></div><p class="help">Build 4 also keeps a best-effort IndexedDB recovery snapshot separately from the primary local save. Undo history remains memory-only.</p><div class="list"><button class="list-row" id="storageBackup"><span>💾 Export a backup now</span><span>JSON</span></button><button class="list-row" id="restoreRecovery"><span>🛟 Restore recovery snapshot</span><span>›</span></button><button class="list-row" id="clearHistory"><span>↶ Clear undo/redo history</span><span>${historyCount}</span></button><button class="list-row" id="clearRecents"><span>🧹 Clear recently used object list</span><span>${state.recentPresetIds.length}</span></button></div>`,m=>{$('#storageBackup',m).onclick=()=>downloadBlob(JSON.stringify(persistentPayload(),null,2),'dango-backup-v4.json','application/json');$('#restoreRecovery',m).onclick=async()=>{const b=await idbLoad();if(!b)return toast('No recovery snapshot found');if(!confirm('Replace the current local state with the recovery snapshot?'))return;state=migrateState(b);saveNow();m.remove();renderAll();toast('Recovery snapshot restored')};$('#clearHistory',m).onclick=()=>{state.history=[];state.future=[];updateUndoRedo();m.remove();toast('Undo history cleared')};$('#clearRecents',m).onclick=()=>{state.recentPresetIds=[];persist();m.remove();toast('Recent objects cleared')}})}
function backupModal(){modal('Backup, restore & import',`<div class="list"><button class="list-row" id="exportBackup"><span>⬇️ Export full Dango backup</span><span>JSON</span></button><label class="list-row" for="importBackup"><span>⬆️ Restore full backup</span><span>Choose file</span></label><input id="importBackup" type="file" accept="application/json,.json" hidden><label class="list-row" for="importProject"><span>📦 Import a Dango room</span><span>.json</span></label><input id="importProject" type="file" accept="application/json,.json" hidden><button class="list-row" id="clearData"><span>🗑️ Reset all local data</span><span>›</span></button></div><p class="help">Backups include rooms, custom shapes, layouts, measurements, walking paths, My Objects, moving boxes, notes and settings.</p>`,m=>{$('#exportBackup',m).onclick=()=>downloadBlob(JSON.stringify(persistentPayload(),null,2),'dango-backup-v4.json','application/json');$('#importBackup',m).onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text()),next=migrateState(data);if(!Array.isArray(next.rooms))throw new Error();snapshot('Restore backup');state=next;saveNow();m.remove();renderAll();toast('Backup restored')}catch{alert('That backup file could not be read.')}};$('#importProject',m).onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text()),room=data.room;if(!room||!Array.isArray(room.layouts))throw new Error();snapshot('Import room');const cp=migrateState({rooms:[room]}).rooms[0];cp.id=uid('room');cp.name=`${cp.name||'Imported Room'} (Imported)`;cp.layouts.forEach(l=>{l.id=uid('layout');l.objects.forEach(o=>o.id=uid('obj'));l.measurements=(l.measurements||[]).map(mm=>({...mm,id:uid('measure')}))});state.rooms.unshift(cp);state.currentRoomId=cp.id;state.currentLayoutId=cp.layouts[0].id;state.view='plan';persist();m.remove();renderAll();toast('Room imported')}catch{alert('That Dango room file could not be read.')}};$('#clearData',m).onclick=async()=>{if(confirm('Reset Dango and delete every locally saved room, template and moving box?')){localStorage.removeItem(STORAGE_KEY);LEGACY_KEYS.forEach(k=>localStorage.removeItem(k));await idbClear();state=defaultState();m.remove();renderAll();maybeShowOnboarding();toast('Local data reset')}}})}
function exportProject(){const r=currentRoom();if(r)downloadBlob(JSON.stringify({dangoProjectVersion:4,room:r},null,2),`${slug(r.name)}.dango.json`,'application/json')}

function onboardingModal(firstRun=true){modal('Welcome to Dango 🍡',`<div class="onboarding-grid"><div><span>1</span><b>Measure your real room</b><p>Create a blank room using the measurements you took. Nothing is filled with demo furniture.</p></div><div><span>2</span><b>Add only what belongs</b><p>Add furniture, doors, windows and fixed features with their real dimensions.</p></div><div><span>3</span><b>Try layouts safely</b><p>Duplicate layouts, check clearances, walking paths and fit suggestions without changing your original arrangement.</p></div><div><span>4</span><b>Your data stays local</b><p>Dango autosaves on this device. Export backups whenever a room matters to you.</p></div></div><div class="form-actions"><button class="secondary-btn" id="skipOnboarding">${firstRun?'Skip':'Close'}</button><button class="primary-btn" id="startDango">${state.rooms.length?'Open Dango':'Create first room'}</button></div>`,m=>{const done=()=>{state.settings.onboardingDone=true;persist();m.remove()};$('#skipOnboarding',m).onclick=done;$('#startDango',m).onclick=()=>{done();if(!state.rooms.length)newRoomModal()}})}
function maybeShowOnboarding(){if(!state.settings.onboardingDone&&!state.rooms.length&&!$('.modal-backdrop'))setTimeout(()=>onboardingModal(true),120)}


function createRoom(data){const w=toCm(data.width,data.unit),h=toCm(data.height,data.unit);if(!w||!h)return toast('Enter valid room measurements.');snapshot('Create room');const layout=newLayout('Layout A'),room={id:uid('room'),name:(data.name||'Untitled Room').trim(),width:Math.max(100,w),height:Math.max(100,h),unit:data.unit||'cm',roomType:data.roomType||'Room',shapeType:'rectangle',points:normalizeRoomPoints(null,Math.max(100,w),Math.max(100,h)),ceilingHeight:0,starred:false,notes:'',createdAt:now(),updatedAt:now(),layouts:[layout]};state.rooms.unshift(room);state.currentRoomId=room.id;state.currentLayoutId=layout.id;state.view='plan';state.zoom=1;state.selectedId=null;persist();renderAll();toast('Room created')}
function saveRoomTemplate(room=currentRoom()){if(!room)return;const name=(prompt('Template name',`${room.name} shell`)||'').trim();if(!name)return;const fixedTypes=new Set(['door','window','outlet','switch','ac','column','radiator','built-in','sink','stairs','drain','router']);const base=room.layouts.find(l=>l.id===state.currentLayoutId)||room.layouts[0],template={id:uid('template'),name,width:room.width,height:room.height,unit:room.unit,roomType:room.roomType,shapeType:room.shapeType,points:deepClone(roomPoints(room)),ceilingHeight:room.ceilingHeight||0,objects:(base?.objects||[]).filter(o=>fixedTypes.has(o.type)).map(o=>deepClone(o)),createdAt:now()};template.objects.forEach(o=>o.id=uid('obj'));state.roomTemplates.unshift(template);persist();toast('Room template saved')}
function createRoomFromTemplate(id){const t=state.roomTemplates.find(x=>x.id===id);if(!t)return toast('Template not found');snapshot('Create room from template');const l=newLayout('Layout A',deepClone(t.objects||[]));l.objects.forEach(o=>o.id=uid('obj'));const room={id:uid('room'),name:t.name,width:t.width,height:t.height,unit:t.unit||state.settings.unit,roomType:t.roomType||'Room',shapeType:t.shapeType||'rectangle',points:normalizeRoomPoints(t.points,t.width,t.height),ceilingHeight:t.ceilingHeight||0,starred:false,notes:'',createdAt:now(),updatedAt:now(),layouts:[l]};state.rooms.unshift(room);state.currentRoomId=room.id;state.currentLayoutId=l.id;state.view='plan';state.zoom=1;state.selectedId=null;persist();renderAll();toast('Room created from template')}



function fitThroughDoor(){const o=objects().find(x=>x.id===state.selectedId);if(!o)return toast('Select the furniture first');const doors=objects().filter(x=>x.type==='door'),access=accessFitSummary(o);if(!doors.length&&!access.known)return toast('Add a door or moving access measurements first');const doorRows=doors.map((d,i)=>{const width=Math.max(d.w,d.h),flat=Math.min(o.w,o.h)<=width,heightOk=!d.doorHeight||!o.height||o.height<=d.doorHeight,turn=doorTurningClearance(d),turnOk=turn>=Math.min(o.w,o.h)*.65,ok=flat&&heightOk;return `<div class="list-row"><span><b>${ok?'✅':'⚠️'} Room door ${i+1}</b><span class="meta">Opening ${display(width,rUnit())}${d.doorHeight?` × ${display(d.doorHeight,rUnit())} high`:''}<br>${flat?'footprint can pass':'smallest side is too wide'} • ${heightOk?'height OK / unknown':'too tall'} • ${turnOk?'turning space looks usable':'turning space may be tight'}</span></span></div>`}).join('');const accessRow=access.known?`<div class="list-row"><span><b>${access.widthOk&&access.heightOk&&access.elevatorOk?'✅':'⚠️'} Saved moving access</b><span class="meta">${access.minAccess?`Narrowest saved access ${display(access.minAccess,state.settings.unit)} • `:''}${access.widthOk?'width likely OK':'width may be too tight'} • ${access.heightOk?'height OK / unknown':'height may be too low'} • ${access.elevatorOk?'elevator footprint looks usable':'elevator footprint may be tight'}</span></span></div>`:'';modal(`Move ${o.name} through access`,`<div class="list">${doorRows}${accessRow}</div><p class="help">This is a practical top-down screening check. Real moving can also depend on tilt, handles, removable parts, hallway turns, stair landings and exact elevator door openings.</p>`)}

